public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int m = sc.nextInt();
        int qx = sc.nextInt();
        int qy = sc.nextInt();
        int ax = sc.nextInt();
        int ay = sc.nextInt();

        // The queen can escape if she can reach any edge in fewer moves
        // than the army can reach her blocking position

        // Queen's distance to nearest edge
        int queenToEdge = Math.min(Math.min(qx - 1, n - qx), Math.min(qy - 1, m - qy));

        // Army's distance to nearest edge from queen's perspective
        // Army needs to get to the same row or column or diagonal to block

        // Check each direction the queen can move
        boolean canEscape = false;

        // Up
        if (qx - 1 >= 0) {
            int armyDist = Math.abs(ax - 1) + Math.abs(ay - qy);
            if (Math.abs(ax - 1) == Math.abs(ay - qy)) {
                armyDist = Math.abs(ax - 1);
            }
            if (qx - 1 < armyDist) {
                canEscape = true;
            }
        }

        // Down
        if (n - qx >= 0) {
            int armyDist = Math.abs(ax - n) + Math.abs(ay - qy);
            if (Math.abs(ax - n) == Math.abs(ay - qy)) {
                armyDist = Math.abs(ax - n);
            }
            if (n - qx < armyDist) {
                canEscape = true;
            }
        }

        // Left
        if (qy - 1 >= 0) {
            int armyDist = Math.abs(ax - qx) + Math.abs(ay - 1);
            if (Math.abs(ax - qx) == Math.abs(ay - 1)) {
                armyDist = Math.abs(ax - qx);
            }
            if (qy - 1 < armyDist) {
                canEscape = true;
            }
        }

        // Right
        if (m - qy >= 0) {
            int armyDist = Math.abs(ax - qx) + Math.abs(ay - m);
            if (Math.abs(ax - qx) == Math.abs(ay - m)) {
                armyDist = Math.abs(ax - qx);
            }
            if (m - qy < armyDist) {
                canEscape = true;
            }
        }

        System.out.println(canEscape ? "YES" : "NO");

        sc.close();
    }
}

