        if (input.isEmpty()) return;

        String[] parts = input.split("\\s+");
        List<Integer> nums = new ArrayList<>();
        for (String s : parts) {
            try {
                nums.add(Integer.parseInt(s));
            } catch (Exception ignored) {
            }
        }

        if (nums.size() < 4) return;

        int qx = nums.get(0);
        int qy = nums.get(1);
        int ax = nums.get(2);
        int ay = nums.get(3);

        // Without the full original statement/test format, use the standard
        // grid-chase criterion on an unbounded grid with both moving one cell
        // per turn in 4 directions: the queen escapes iff her parity differs
        // from the army's starting parity; otherwise the army can eventually catch.
        //
        // Equivalent: if Manhattan distance parity is even -> caught, else escape.
        int parityQueen = (qx + qy) & 1;
        int parityArmy = (ax + ay) & 1;

        if (parityQueen == parityArmy) {
            System.out.println("Caught");
